package com.combatbreakdown;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(CombatBreakdownConfig.GROUP)
public interface CombatBreakdownConfig extends Config
{
	String GROUP = "combatbreakdown";

	enum HudVisibility
	{
		IN_COMBAT_ONLY("In combat only"),
		WHILE_SESSION_ACTIVE("While session active"),
		OFF("Hidden");

		private final String label;

		HudVisibility(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	@ConfigSection(
		name = "HUD Overlay",
		description = "Compact on-screen combat analytics HUD",
		position = 0
	)
	String hudSection = "hudSection";

	@ConfigSection(
		name = "Session & Supplies",
		description = "Combat timer, supply burn tracking, and history persistence",
		position = 1
	)
	String sessionSection = "sessionSection";

	@ConfigItem(
		keyName = "hudVisibility",
		name = "HUD visibility",
		description = "Choose when the on-screen Combat Breakdown HUD is displayed",
		section = hudSection,
		position = 0
	)
	default HudVisibility hudVisibility()
	{
		return HudVisibility.IN_COMBAT_ONLY;
	}

	@ConfigItem(
		keyName = "hudShowDamageTaken",
		name = "Show damage taken in HUD",
		description = "Include damage taken and healing received in the compact HUD",
		section = hudSection,
		position = 1
	)
	default boolean hudShowDamageTaken()
	{
		return true;
	}

	@ConfigItem(
		keyName = "hudShowSupplyBurn",
		name = "Show profit / supply burn in HUD",
		description = "Include net profit/hr or supply burn/hr (or item counts on Ironman) in the HUD",
		section = hudSection,
		position = 2
	)
	default boolean hudShowSupplyBurn()
	{
		return true;
	}

	@ConfigItem(
		keyName = "hudShowCombatXp",
		name = "Show combat XP/hr in HUD",
		description = "Include total combat XP/hr in the compact on-screen HUD",
		section = hudSection,
		position = 3
	)
	default boolean hudShowCombatXp()
	{
		return false;
	}

	@Range(min = 3, max = 30)
	@ConfigItem(
		keyName = "idleTimeoutTicks",
		name = "Active combat idle timeout (ticks)",
		description = "Game ticks (0.6s each) without combat hits before the Active DPS timer pauses",
		section = sessionSection,
		position = 0
	)
	default int idleTimeoutTicks()
	{
		return 10;
	}

	@ConfigItem(
		keyName = "trackSupplyBurn",
		name = "Track supply consumption",
		description = "Track food eaten, potion doses drunk, and ammo/runes/cannonballs spent in combat",
		section = sessionSection,
		position = 1
	)
	default boolean trackSupplyBurn()
	{
		return true;
	}

	@ConfigItem(
		keyName = "hideGpOnIronman",
		name = "Hide GE GP values on Ironman",
		description = "Show supply counts without GE GP totals when logged into an Ironman or UIM account",
		section = sessionSection,
		position = 2
	)
	default boolean hideGpOnIronman()
	{
		return true;
	}

	@ConfigItem(
		keyName = "persistTargetHistory",
		name = "Save per-target history",
		description = "Persist aggregated per-NPC kill count, DPS, and fastest kill times across sessions",
		section = sessionSection,
		position = 3
	)
	default boolean persistTargetHistory()
	{
		return true;
	}
}

package com.combatbreakdown;

import com.combatbreakdown.logic.CombatSessionTracker;
import com.combatbreakdown.logic.CombatSessionTracker.SessionSnapshot;
import com.combatbreakdown.logic.HistorySerializer;
import com.combatbreakdown.logic.HitsplatClassifier;
import com.combatbreakdown.logic.SupplyBurnTracker;
import com.combatbreakdown.logic.SupplyBurnTracker.BurnSnapshot;
import com.combatbreakdown.model.FightRecord;
import com.combatbreakdown.model.HitCategory;
import com.combatbreakdown.ui.CombatBreakdownPanel;
import com.google.gson.Gson;
import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.Getter;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.GameState;
import net.runelite.api.Hitsplat;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.ItemSpawned;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;

@PluginDescriptor(
	name = "Combat Breakdown",
	description = "Live active & session DPS, sparkline, hit distribution, per-weapon and A/B comparisons, spec & XP/hr, loot vs. supply burn, and per-target fight history",
	tags = {"combat", "dps", "pvm", "bossing", "slayer", "analytics", "meter", "accuracy", "supplies", "profit", "history"}
)
public class CombatBreakdownPlugin extends Plugin
{
	private static final String KEY_TARGET_HISTORY = "targetHistoryJson";

	private static final Set<Skill> TRACKED_COMBAT_SKILLS = EnumSet.of(
		Skill.ATTACK,
		Skill.STRENGTH,
		Skill.DEFENCE,
		Skill.RANGED,
		Skill.MAGIC,
		Skill.HITPOINTS,
		Skill.SLAYER
	);

	private static final int[] RUNE_POUCH_TYPE_VARBITS = {
		VarbitID.RUNE_POUCH_TYPE_1,
		VarbitID.RUNE_POUCH_TYPE_2,
		VarbitID.RUNE_POUCH_TYPE_3,
		VarbitID.RUNE_POUCH_TYPE_4,
		VarbitID.RUNE_POUCH_TYPE_5,
		VarbitID.RUNE_POUCH_TYPE_6
	};

	private static final int[] RUNE_POUCH_QTY_VARBITS = {
		VarbitID.RUNE_POUCH_QUANTITY_1,
		VarbitID.RUNE_POUCH_QUANTITY_2,
		VarbitID.RUNE_POUCH_QUANTITY_3,
		VarbitID.RUNE_POUCH_QUANTITY_4,
		VarbitID.RUNE_POUCH_QUANTITY_5,
		VarbitID.RUNE_POUCH_QUANTITY_6
	};

	private static final Set<Integer> RUNE_POUCH_IDS = new HashSet<>();
	private static final Set<Integer> RUNE_POUCH_VARBITS = new HashSet<>();

	static
	{
		RUNE_POUCH_IDS.add(ItemID.BH_RUNE_POUCH);
		RUNE_POUCH_IDS.add(ItemID.BH_RUNE_POUCH_TROUVER);
		RUNE_POUCH_IDS.add(ItemID.DIVINE_RUNE_POUCH);
		RUNE_POUCH_IDS.add(ItemID.DIVINE_RUNE_POUCH_TROUVER);
		for (int v : RUNE_POUCH_TYPE_VARBITS)
		{
			RUNE_POUCH_VARBITS.add(v);
		}
		for (int v : RUNE_POUCH_QTY_VARBITS)
		{
			RUNE_POUCH_VARBITS.add(v);
		}
	}

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private Gson gson;

	@Inject
	private CombatBreakdownConfig config;

	@Inject
	private com.combatbreakdown.overlay.CombatHudOverlay hudOverlay;

	private final CombatSessionTracker sessionTracker = new CombatSessionTracker();
	private final SupplyBurnTracker supplyTracker = new SupplyBurnTracker();
	private final Map<Skill, Integer> lastSkillXp = new EnumMap<>(Skill.class);
	private int lastSpecEnergy = -1;

	private HistorySerializer historySerializer;
	private NavigationButton navButton;
	private CombatBreakdownPanel panel;

	private volatile boolean ironmanAccount;
	private volatile boolean panelDirty;

	@Getter
	private volatile SessionSnapshot latestSession;

	@Getter
	private volatile BurnSnapshot latestBurn;

	private final SupplyBurnTracker.ItemMetaLookup itemMetaLookup = new SupplyBurnTracker.ItemMetaLookup()
	{
		@Override
		public String getName(int itemId)
		{
			if (itemId <= 0)
			{
				return "";
			}
			ItemComposition comp = itemManager.getItemComposition(itemId);
			return comp != null && comp.getName() != null ? comp.getName() : "";
		}

		@Override
		public long getUnitPrice(int itemId)
		{
			return itemId > 0 ? Math.max(0L, itemManager.getItemPrice(itemId)) : 0L;
		}
	};

	@Provides
	CombatBreakdownConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CombatBreakdownConfig.class);
	}

	@Override
	protected void startUp()
	{
		historySerializer = new HistorySerializer(gson);
		sessionTracker.setIdleTimeoutTicks(config.idleTimeoutTicks());

		if (config.persistTargetHistory())
		{
			String saved = configManager.getConfiguration(CombatBreakdownConfig.GROUP, KEY_TARGET_HISTORY);
			sessionTracker.loadPersistedSummaries(historySerializer.deserialize(saved));
		}

		publishSnapshots();

		panel = new CombatBreakdownPanel(this, configManager, itemManager);
		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/com/combatbreakdown/icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Combat Breakdown")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		overlayManager.add(hudOverlay);

		clientThread.invokeLater(this::syncAccountAndEquipmentOnClientThread);
	}

	@Override
	protected void shutDown()
	{
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
		overlayManager.remove(hudOverlay);
		if (panel != null)
		{
			panel.dispose();
			panel = null;
		}
		synchronized (this)
		{
			sessionTracker.resetSessionOnly();
			sessionTracker.clearPinnedComparison();
			supplyTracker.reset();
			lastSkillXp.clear();
			lastSpecEnergy = -1;
		}
		latestSession = null;
		latestBurn = null;
		ironmanAccount = false;
		panelDirty = false;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			synchronized (this)
			{
				supplyTracker.invalidateBaseline();
				lastSkillXp.clear();
				lastSpecEnergy = -1;
			}
		}
		else if (state == GameState.LOGGED_IN)
		{
			clientThread.invokeLater(this::syncAccountAndEquipmentOnClientThread);
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!CombatBreakdownConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		synchronized (this)
		{
			sessionTracker.setIdleTimeoutTicks(config.idleTimeoutTicks());
		}
		publishSnapshots();
		notifyPanel();
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		Skill skill = event.getSkill();
		if (!TRACKED_COMBAT_SKILLS.contains(skill))
		{
			return;
		}
		int newXp = event.getXp();
		int tick = client.getTickCount();
		synchronized (this)
		{
			Integer prev = lastSkillXp.put(skill, newXp);
			if (prev != null && newXp > prev)
			{
				sessionTracker.recordSkillXp(skill, newXp - prev, tick);
				panelDirty = true;
			}
		}
	}

	@Subscribe
	public void onNpcLootReceived(NpcLootReceived event)
	{
		if (event.getNpc() == null || event.getItems() == null || event.getItems().isEmpty())
		{
			return;
		}
		long totalDropGp = 0L;
		synchronized (this)
		{
			if (sessionTracker.isPaused())
			{
				return;
			}
			for (ItemStack stack : event.getItems())
			{
				if (stack == null || stack.getId() <= 0 || stack.getQuantity() <= 0)
				{
					continue;
				}
				int canonicalId = itemManager.canonicalize(stack.getId());
				totalDropGp += supplyTracker.recordLootDrop(canonicalId, stack.getQuantity(), itemMetaLookup);
			}
			if (totalDropGp > 0)
			{
				sessionTracker.recordNpcLootValue(event.getNpc().getName(), totalDropGp);
				if (config.persistTargetHistory())
				{
					persistHistoryLocked();
				}
			}
		}
		publishSnapshots();
		panelDirty = true;
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (!config.trackSupplyBurn())
		{
			return;
		}
		String option = event.getMenuOption();
		if (option == null)
		{
			return;
		}
		if ("Eat".equalsIgnoreCase(option) || "Drink".equalsIgnoreCase(option))
		{
			int rawId = event.getItemId();
			int canonicalId = rawId > 0 ? itemManager.canonicalize(rawId) : -1;
			synchronized (this)
			{
				supplyTracker.recordConsumeAction(option, canonicalId, client.getTickCount());
			}
		}
	}

	@Subscribe
	public void onItemSpawned(ItemSpawned event)
	{
		if (!config.trackSupplyBurn() || event.getTile() == null || event.getItem() == null)
		{
			return;
		}
		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return;
		}
		WorldPoint playerLoc = local.getWorldLocation();
		WorldPoint tileLoc = event.getTile().getWorldLocation();
		if (playerLoc != null && playerLoc.equals(tileLoc))
		{
			int canonicalId = itemManager.canonicalize(event.getItem().getId());
			synchronized (this)
			{
				supplyTracker.recordDroppedOnSelfTile(canonicalId, client.getTickCount());
			}
		}
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		Actor actor = event.getActor();
		Hitsplat splat = event.getHitsplat();
		Player local = client.getLocalPlayer();
		if (actor == null || splat == null || local == null)
		{
			return;
		}

		int tick = client.getTickCount();
		if (actor == local)
		{
			HitCategory cat = HitsplatClassifier.classifyIncoming(splat.getHitsplatType(), splat.getAmount());
			if (cat != HitCategory.OTHER)
			{
				synchronized (this)
				{
					sessionTracker.onIncomingHitsplat(cat, splat.getAmount(), tick);
				}
				publishSnapshots();
				panelDirty = true;
			}
			return;
		}

		if (actor instanceof NPC)
		{
			NPC npc = (NPC) actor;
			HitCategory cat = HitsplatClassifier.classifyOutgoing(splat.getHitsplatType(), splat.getAmount(), splat.isMine());
			if (cat != HitCategory.OTHER)
			{
				synchronized (this)
				{
					sessionTracker.onOutgoingHitsplat(
						npc.getIndex(),
						npc.getName(),
						npc.getCombatLevel(),
						cat,
						splat.getAmount(),
						tick
					);
				}
				publishSnapshots();
				panelDirty = true;
			}
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		if (!(event.getActor() instanceof NPC))
		{
			return;
		}
		NPC npc = (NPC) event.getActor();
		FightRecord completed;
		synchronized (this)
		{
			completed = sessionTracker.onNpcDeath(npc.getIndex(), client.getTickCount(), System.currentTimeMillis());
			if (completed != null && config.persistTargetHistory())
			{
				persistHistoryLocked();
			}
		}
		if (completed != null)
		{
			publishSnapshots();
			panelDirty = true;
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int id = event.getContainerId();
		if (id != InventoryID.INV && id != InventoryID.WORN)
		{
			return;
		}
		if (id == InventoryID.WORN)
		{
			syncWeaponOnClientThread();
		}
		if (config.trackSupplyBurn())
		{
			processSupplyDeltaOnClientThread();
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		int varbit = event.getVarbitId();
		if (varbit == VarbitID.IRONMAN)
		{
			ironmanAccount = client.getVarbitValue(VarbitID.IRONMAN) != 0;
			panelDirty = true;
		}
		else if (event.getVarpId() == VarPlayerID.SA_ENERGY)
		{
			int nowSpec = client.getVarpValue(VarPlayerID.SA_ENERGY);
			synchronized (this)
			{
				if (lastSpecEnergy >= 0 && nowSpec < lastSpecEnergy)
				{
					sessionTracker.recordSpecialAttackUsed(client.getTickCount());
					panelDirty = true;
				}
				lastSpecEnergy = nowSpec;
			}
		}
		else if (config.trackSupplyBurn() && RUNE_POUCH_VARBITS.contains(varbit))
		{
			processSupplyDeltaOnClientThread();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		boolean activeBefore;
		boolean started;
		synchronized (this)
		{
			activeBefore = sessionTracker.isInActiveCombat();
			sessionTracker.onGameTick(client.getTickCount());
			started = sessionTracker.snapshot().isSessionStarted();
		}
		if (started || activeBefore || panelDirty)
		{
			publishSnapshots();
			panelDirty = false;
			notifyPanel();
		}
	}

	public boolean shouldDisplayGpValues()
	{
		return !(ironmanAccount && config.hideGpOnIronman());
	}

	public boolean isIronmanAccount()
	{
		return ironmanAccount;
	}

	public void togglePaused()
	{
		synchronized (this)
		{
			sessionTracker.setPaused(!sessionTracker.isPaused());
		}
		publishSnapshots();
		notifyPanel();
	}

	public void pinCurrentRunAndReset()
	{
		synchronized (this)
		{
			SessionSnapshot s = sessionTracker.snapshot();
			if (!s.isSessionStarted())
			{
				return;
			}
			BurnSnapshot b = supplyTracker.snapshot(s.getSessionSeconds(), s.getSessionKills());
			sessionTracker.pinCurrentComparison(b.getGpPerHour(), b.getNetProfitPerHour());
			sessionTracker.resetSessionOnly();
			supplyTracker.reset();
		}
		publishSnapshots();
		notifyPanel();
		clientThread.invokeLater(this::syncAccountAndEquipmentOnClientThread);
	}

	public void unpinComparison()
	{
		synchronized (this)
		{
			sessionTracker.clearPinnedComparison();
		}
		publishSnapshots();
		notifyPanel();
	}

	public void resetSession()
	{
		synchronized (this)
		{
			sessionTracker.resetSessionOnly();
			supplyTracker.reset();
		}
		publishSnapshots();
		notifyPanel();
		clientThread.invokeLater(this::syncAccountAndEquipmentOnClientThread);
	}

	public void clearHistory()
	{
		synchronized (this)
		{
			sessionTracker.clearPersistedHistory();
			configManager.unsetConfiguration(CombatBreakdownConfig.GROUP, KEY_TARGET_HISTORY);
		}
		publishSnapshots();
		notifyPanel();
	}

	public String buildSummaryText()
	{
		synchronized (this)
		{
			SessionSnapshot s = sessionTracker.snapshot();
			BurnSnapshot b = supplyTracker.snapshot(s.getSessionSeconds(), s.getSessionKills());
			return sessionTracker.formatSummaryText(b.getTotalCostGp(), b.getTotalLootGp(), shouldDisplayGpValues());
		}
	}

	public String buildHistoryCsv()
	{
		synchronized (this)
		{
			return sessionTracker.formatHistoryCsv();
		}
	}

	private void syncAccountAndEquipmentOnClientThread()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		ironmanAccount = client.getVarbitValue(VarbitID.IRONMAN) != 0;
		synchronized (this)
		{
			lastSpecEnergy = client.getVarpValue(VarPlayerID.SA_ENERGY);
			for (Skill skill : TRACKED_COMBAT_SKILLS)
			{
				lastSkillXp.put(skill, client.getSkillExperience(skill));
			}
		}
		syncWeaponOnClientThread();
		if (config.trackSupplyBurn())
		{
			processSupplyDeltaOnClientThread();
		}
		publishSnapshots();
		notifyPanel();
	}

	private void syncWeaponOnClientThread()
	{
		ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		if (worn == null)
		{
			synchronized (this)
			{
				sessionTracker.updateEquippedWeapon(-1, "Unarmed");
			}
			return;
		}
		Item weapon = worn.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
		if (weapon == null || weapon.getId() <= 0 || weapon.getQuantity() <= 0)
		{
			synchronized (this)
			{
				sessionTracker.updateEquippedWeapon(-1, "Unarmed");
			}
			return;
		}
		int canonicalId = itemManager.canonicalize(weapon.getId());
		ItemComposition comp = itemManager.getItemComposition(canonicalId);
		String name = comp != null && comp.getName() != null ? comp.getName() : ("Weapon #" + canonicalId);
		synchronized (this)
		{
			sessionTracker.updateEquippedWeapon(canonicalId, name);
		}
	}

	private void processSupplyDeltaOnClientThread()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		ItemContainer invContainer = client.getItemContainer(InventoryID.INV);
		ItemContainer wornContainer = client.getItemContainer(InventoryID.WORN);
		Map<Integer, Integer> invCounts = readContainer(invContainer);

		int ammoId = -1;
		int ammoQty = 0;
		int weaponId = -1;
		int weaponQty = 0;
		if (wornContainer != null)
		{
			Item ammo = wornContainer.getItem(EquipmentInventorySlot.AMMO.getSlotIdx());
			if (ammo != null && ammo.getId() > 0 && ammo.getQuantity() > 0)
			{
				ammoId = itemManager.canonicalize(ammo.getId());
				ammoQty = ammo.getQuantity();
			}
			Item wep = wornContainer.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
			if (wep != null && wep.getId() > 0 && wep.getQuantity() > 0)
			{
				weaponId = itemManager.canonicalize(wep.getId());
				weaponQty = wep.getQuantity();
			}
		}

		Map<Integer, Integer> pouchRunes = hasRunePouch(invCounts) ? readRunePouchRunes() : Collections.emptyMap();
		boolean storageOpen = isStorageUiOpen();
		int tick = client.getTickCount();

		long deltaGp;
		synchronized (this)
		{
			deltaGp = supplyTracker.onStateUpdate(
				invCounts,
				ammoId,
				ammoQty,
				weaponId,
				weaponQty,
				pouchRunes,
				storageOpen,
				sessionTracker.isInActiveCombat(),
				sessionTracker.isPaused(),
				tick,
				itemMetaLookup
			);
			if (deltaGp > 0)
			{
				sessionTracker.addSupplyCostGp(deltaGp);
			}
		}
		if (deltaGp > 0)
		{
			publishSnapshots();
			panelDirty = true;
		}
	}

	private boolean isStorageUiOpen()
	{
		return isWidgetVisible(InterfaceID.Bankmain.UNIVERSE)
			|| isWidgetVisible(InterfaceID.BankDepositbox.UNIVERSE)
			|| isWidgetVisible(InterfaceID.GeOffers.UNIVERSE)
			|| isWidgetVisible(InterfaceID.Trademain.UNIVERSE)
			|| isWidgetVisible(InterfaceID.Shopmain.UNIVERSE)
			|| isWidgetVisible(InterfaceID.SharedBank.UNIVERSE);
	}

	private boolean isWidgetVisible(int packedWidgetId)
	{
		Widget widget = client.getWidget(packedWidgetId);
		return widget != null && !widget.isHidden();
	}

	private Map<Integer, Integer> readContainer(ItemContainer container)
	{
		if (container == null || container.getItems() == null)
		{
			return Collections.emptyMap();
		}
		Map<Integer, Integer> counts = new HashMap<>();
		for (Item item : container.getItems())
		{
			if (item == null || item.getId() <= 0 || item.getQuantity() <= 0)
			{
				continue;
			}
			int canonicalId = itemManager.canonicalize(item.getId());
			counts.merge(canonicalId, item.getQuantity(), Integer::sum);
		}
		return counts;
	}

	private boolean hasRunePouch(Map<Integer, Integer> invCounts)
	{
		for (int pouchId : RUNE_POUCH_IDS)
		{
			if (invCounts.getOrDefault(pouchId, 0) > 0)
			{
				return true;
			}
		}
		return false;
	}

	private Map<Integer, Integer> readRunePouchRunes()
	{
		EnumComposition runeEnum = client.getEnum(EnumID.RUNEPOUCH_RUNE);
		if (runeEnum == null)
		{
			return Collections.emptyMap();
		}
		Map<Integer, Integer> runes = new HashMap<>(8);
		for (int i = 0; i < RUNE_POUCH_TYPE_VARBITS.length; i++)
		{
			int typeId = client.getVarbitValue(RUNE_POUCH_TYPE_VARBITS[i]);
			int qty = client.getVarbitValue(RUNE_POUCH_QTY_VARBITS[i]);
			if (typeId <= 0 || qty <= 0)
			{
				continue;
			}
			int runeItemId = runeEnum.getIntValue(typeId);
			if (runeItemId > 0)
			{
				runes.merge(runeItemId, qty, Integer::sum);
			}
		}
		return runes;
	}

	private void persistHistoryLocked()
	{
		String json = historySerializer.serialize(sessionTracker.getTargetSummariesSorted());
		configManager.setConfiguration(CombatBreakdownConfig.GROUP, KEY_TARGET_HISTORY, json);
	}

	private void publishSnapshots()
	{
		synchronized (this)
		{
			SessionSnapshot s = sessionTracker.snapshot();
			BurnSnapshot b = supplyTracker.snapshot(s.getSessionSeconds(), s.getSessionKills());
			latestSession = s;
			latestBurn = b;
		}
	}

	private void notifyPanel()
	{
		CombatBreakdownPanel current = panel;
		if (current != null)
		{
			SwingUtilities.invokeLater(current::refresh);
		}
	}
}

package com.combatbreakdown.logic;

import com.combatbreakdown.model.FightRecord;
import com.combatbreakdown.model.HitCategory;
import com.combatbreakdown.model.HitDistribution;
import com.combatbreakdown.model.PinnedComparison;
import com.combatbreakdown.model.StatusDamageBreakdown;
import com.combatbreakdown.model.TargetSummary;
import com.combatbreakdown.model.WeaponStats;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.Deque;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import javax.annotation.Nullable;
import lombok.Value;
import net.runelite.api.Skill;

public final class CombatSessionTracker
{
	public static final int MAX_RECENT_FIGHTS = 40;
	public static final int ROLLING_WINDOW_TICKS = 50; // 30 seconds
	private static final int SPARKLINE_INTERVAL_TICKS = 5; // 3 seconds
	private static final int MAX_SPARKLINE_POINTS = 40;
	private static final int ABANDONED_NPC_TICKS = 100;

	private static final class ActiveNpcFight
	{
		final int npcIndex;
		final String npcName;
		final int combatLevel;
		final int firstHitTick;
		int lastActivityTick;
		long directDamage;
		long statusDamage;
		int hitsLanded;
		int misses;
		int maxHit;
		int lastDirectDamage;
		long damageTaken;
		long healingReceived;
		final Map<String, Long> damageByWeapon = new HashMap<>();

		ActiveNpcFight(int npcIndex, String npcName, int combatLevel, int tick)
		{
			this.npcIndex = npcIndex;
			this.npcName = npcName != null && !npcName.isEmpty() ? npcName : "Unknown NPC";
			this.combatLevel = combatLevel;
			this.firstHitTick = tick;
			this.lastActivityTick = tick;
		}

		String getPrimaryWeaponName()
		{
			String best = "Unarmed";
			long bestDmg = -1L;
			for (Map.Entry<String, Long> entry : damageByWeapon.entrySet())
			{
				if (entry.getValue() > bestDmg)
				{
					bestDmg = entry.getValue();
					best = entry.getKey();
				}
			}
			return best;
		}
	}

	@Value
	private static class TimedDamage
	{
		int tick;
		int damage;
	}

	@Value
	public static class SpecSnapshot
	{
		int uses;
		int hits;
		int misses;
		long totalDamage;
		int maxHit;

		public int getTotalSplats()
		{
			return hits + misses;
		}

		public double getAccuracyPercent()
		{
			int total = getTotalSplats();
			return total > 0 ? (hits * 100.0) / total : 0.0;
		}

		public double getAveragePerUse()
		{
			return uses > 0 ? ((double) totalDamage) / uses : 0.0;
		}
	}

	@Value
	public static class SkillXpEntry
	{
		Skill skill;
		long xpGained;
		double xpPerHour;
	}

	private int idleTimeoutTicks = 10;
	private boolean paused;
	private boolean sessionStarted;

	// Confirmed active combat ticks (excludes trailing idle cooldowns after combat stops)
	private boolean inActiveBout;
	private int activeTicks;
	private int pendingActiveTicks;
	private final Map<Integer, Integer> pendingWeaponTicks = new HashMap<>();
	private int lastActiveTickCounted = -10000;

	private int sessionTicks;
	private int lastCombatTick = -10000;
	private int currentTick;
	private int currentWeaponId = -1;
	private String currentWeaponName = "Unarmed";

	private long totalDirectDamage;
	private int totalHitsLanded;
	private int totalMisses;
	private int sessionKills;

	// Streaks & finishing hits
	private int currentHitStreak;
	private int bestHitStreak;
	private int currentMissStreak;
	private int worstMissStreak;
	private long totalKillingHitDamage;
	private int killingHitCount;

	// Rolling 30s DPS & sparkline history
	private final Deque<TimedDamage> rollingWindow = new ArrayDeque<>();
	private long rollingWindowDamage;
	private final Deque<Double> dpsSparkline = new ArrayDeque<>();
	private int lastSparklineTick = -10000;

	// Special attack tracking
	private int lastSpecUsedTick = -100;
	private int specUses;
	private int specHits;
	private int specMisses;
	private long specTotalDamage;
	private int specMaxHit;

	// Combat XP tracking (includes a short pre-hit buffer since OSRS XP drops precede hitsplats by 1-2 ticks)
	private final Map<Skill, Long> xpGainedBySkill = new EnumMap<>(Skill.class);
	private final Map<Skill, Long> pendingPreSessionXp = new EnumMap<>(Skill.class);
	private int pendingPreSessionXpTick = -10000;
	private long totalCombatXpGained;

	private final HitDistribution hitDistribution = new HitDistribution();
	private final StatusDamageBreakdown statusAndDefense = new StatusDamageBreakdown();
	private final Map<Integer, WeaponStats> weaponStatsById = new LinkedHashMap<>();
	private final Map<Integer, ActiveNpcFight> activeNpcs = new HashMap<>();
	private final Deque<FightRecord> recentFights = new ArrayDeque<>();
	private final Map<String, TargetSummary> targetSummaries = new LinkedHashMap<>();

	private int focusNpcIndex = -1;
	private String lastTargetName = "";
	private int lastTargetCombatLevel;
	private long unattributedSupplyCostGp;

	@Nullable
	private PinnedComparison pinnedComparison;

	public void setIdleTimeoutTicks(int idleTimeoutTicks)
	{
		this.idleTimeoutTicks = Math.max(2, Math.min(50, idleTimeoutTicks));
	}

	public void setPaused(boolean paused)
	{
		this.paused = paused;
	}

	public boolean isPaused()
	{
		return paused;
	}

	public boolean isInActiveCombat()
	{
		return sessionStarted && !paused && inActiveBout && (currentTick - lastCombatTick) <= idleTimeoutTicks;
	}

	public void updateEquippedWeapon(int weaponItemId, @Nullable String weaponName)
	{
		this.currentWeaponId = weaponItemId;
		this.currentWeaponName = (weaponName != null && !weaponName.trim().isEmpty()) ? weaponName.trim() : "Unarmed";
	}

	public void recordSpecialAttackUsed(int tick)
	{
		if (paused)
		{
			return;
		}
		this.currentTick = tick;
		this.lastSpecUsedTick = tick;
		this.specUses++;
	}

	public void recordSkillXp(Skill skill, long deltaXp, int tick)
	{
		if (paused || skill == null || deltaXp <= 0)
		{
			return;
		}
		this.currentTick = tick;
		if (!sessionStarted)
		{
			// Buffer up to 5 ticks so the first attack's XP drop (which fires before the hitsplat) is never lost.
			if ((tick - pendingPreSessionXpTick) > 5)
			{
				pendingPreSessionXp.clear();
			}
			pendingPreSessionXpTick = tick;
			pendingPreSessionXp.merge(skill, deltaXp, Long::sum);
			return;
		}
		// Require recent combat activity so out-of-combat teleports/alchs do not inflate Combat XP/hr.
		if (!inActiveBout && (tick - lastCombatTick) > 6)
		{
			return;
		}
		xpGainedBySkill.merge(skill, deltaXp, Long::sum);
		totalCombatXpGained += deltaXp;
	}

	public void addSupplyCostGp(long gpCost)
	{
		if (gpCost > 0 && !paused)
		{
			unattributedSupplyCostGp += gpCost;
		}
	}

	public void recordNpcLootValue(String npcName, long lootGp)
	{
		if (lootGp <= 0 || npcName == null || npcName.trim().isEmpty())
		{
			return;
		}
		String cleanName = npcName.trim();
		TargetSummary summary = targetSummaries.get(cleanName);
		if (summary != null)
		{
			summary.addLootValueGp(lootGp);
		}
		for (FightRecord recent : recentFights)
		{
			if (cleanName.equals(recent.getNpcName()))
			{
				recent.setLootValueGp(recent.getLootValueGp() + lootGp);
				break;
			}
		}
	}

	public void pinCurrentComparison(long supplyBurnPerHour, long netProfitPerHour)
	{
		SessionSnapshot s = snapshot();
		String weapon = !s.getWeapons().isEmpty() ? s.getWeapons().get(0).getWeaponName() : currentWeaponName;
		String label = !s.getActiveTargetName().isEmpty()
			? (s.getActiveTargetName() + " (" + weapon + ")")
			: weapon;
		this.pinnedComparison = new PinnedComparison(
			label,
			weapon,
			s.getActiveDps(),
			s.getSessionDps(),
			s.getAccuracyPercent(),
			s.getMaxHit(),
			s.getKillsPerHour(),
			s.getCombatXpPerHour(),
			supplyBurnPerHour,
			netProfitPerHour
		);
	}

	public void clearPinnedComparison()
	{
		this.pinnedComparison = null;
	}

	@Nullable
	public PinnedComparison getPinnedComparison()
	{
		return pinnedComparison;
	}

	public void onGameTick(int tick)
	{
		this.currentTick = tick;
		pruneRollingWindow(tick);

		if (!sessionStarted || paused)
		{
			return;
		}
		sessionTicks++;

		if (inActiveBout)
		{
			if ((tick - lastCombatTick) <= idleTimeoutTicks)
			{
				if (tick > lastActiveTickCounted)
				{
					pendingActiveTicks++;
					pendingWeaponTicks.merge(currentWeaponId, 1, Integer::sum);
					lastActiveTickCounted = tick;
				}
				if ((tick - lastSparklineTick) >= SPARKLINE_INTERVAL_TICKS)
				{
					recordSparklineSample(tick);
				}
			}
			else
			{
				// Idle timeout expired with no follow-up hit: discard dead trailing ticks from Active DPS.
				endActiveBoutDiscardingTail();
			}
		}

		// Evict abandoned non-killed NPCs to keep memory bounded.
		if (!activeNpcs.isEmpty())
		{
			Iterator<Map.Entry<Integer, ActiveNpcFight>> it = activeNpcs.entrySet().iterator();
			while (it.hasNext())
			{
				ActiveNpcFight fight = it.next().getValue();
				if ((tick - fight.lastActivityTick) > ABANDONED_NPC_TICKS)
				{
					it.remove();
					if (fight.npcIndex == focusNpcIndex)
					{
						focusNpcIndex = -1;
					}
				}
			}
		}
	}

	public void onOutgoingHitsplat(int npcIndex, String npcName, int combatLevel, HitCategory category, int amount, int tick)
	{
		if (paused || category == HitCategory.OTHER)
		{
			return;
		}
		this.currentTick = tick;
		pruneRollingWindow(tick);

		if (category.isStatusDamage())
		{
			// Only attribute status splats to NPCs the player has already directly engaged.
			ActiveNpcFight engaged = activeNpcs.get(npcIndex);
			if (engaged == null)
			{
				return;
			}
			int cleanStatus = Math.max(0, amount);
			markCombatActivity(tick);
			engaged.lastActivityTick = tick;
			engaged.statusDamage += cleanStatus;
			statusAndDefense.recordOutgoingStatus(category, cleanStatus);
			addRollingDamage(tick, cleanStatus);
			return;
		}

		if (!category.isDirectOutgoing())
		{
			return;
		}

		markCombatActivity(tick);
		ActiveNpcFight fight = activeNpcs.computeIfAbsent(npcIndex,
			k -> new ActiveNpcFight(npcIndex, npcName, combatLevel, tick));
		fight.lastActivityTick = tick;
		focusNpcIndex = npcIndex;
		lastTargetName = fight.npcName;
		lastTargetCombatLevel = fight.combatLevel;

		boolean isMaxSplat = category == HitCategory.DIRECT_MAX_HIT;
		int cleanDmg = category == HitCategory.DIRECT_MISS ? 0 : Math.max(0, amount);
		boolean isSpecHit = (tick - lastSpecUsedTick) >= 0 && (tick - lastSpecUsedTick) <= 2;

		if (cleanDmg > 0)
		{
			totalHitsLanded++;
			totalDirectDamage += cleanDmg;
			fight.hitsLanded++;
			fight.directDamage += cleanDmg;
			fight.lastDirectDamage = cleanDmg;
			if (cleanDmg > fight.maxHit)
			{
				fight.maxHit = cleanDmg;
			}
			currentHitStreak++;
			currentMissStreak = 0;
			if (currentHitStreak > bestHitStreak)
			{
				bestHitStreak = currentHitStreak;
			}
			addRollingDamage(tick, cleanDmg);
			if (isSpecHit)
			{
				specHits++;
				specTotalDamage += cleanDmg;
				if (cleanDmg > specMaxHit)
				{
					specMaxHit = cleanDmg;
				}
			}
		}
		else
		{
			totalMisses++;
			fight.misses++;
			currentMissStreak++;
			currentHitStreak = 0;
			if (currentMissStreak > worstMissStreak)
			{
				worstMissStreak = currentMissStreak;
			}
			if (isSpecHit)
			{
				specMisses++;
			}
		}

		hitDistribution.record(cleanDmg, isMaxSplat);

		WeaponStats weapon = weaponStatsById.computeIfAbsent(currentWeaponId,
			id -> new WeaponStats(currentWeaponId, currentWeaponName));
		weapon.recordHit(cleanDmg, isMaxSplat);
		if (lastActiveTickCounted == tick && weapon.toSnapshot().getActiveTicks() == 0)
		{
			weapon.addActiveTick();
		}
		fight.damageByWeapon.merge(currentWeaponName, (long) cleanDmg, Long::sum);
	}

	public void onIncomingHitsplat(HitCategory category, int amount, int tick)
	{
		if (paused || category == HitCategory.OTHER)
		{
			return;
		}
		this.currentTick = tick;

		// Ignore passive out-of-combat regen/heals if no session has started yet.
		if (!sessionStarted && category == HitCategory.HEAL)
		{
			return;
		}

		if (category != HitCategory.HEAL)
		{
			markCombatActivity(tick);
		}

		statusAndDefense.recordIncoming(category, amount);

		ActiveNpcFight focus = activeNpcs.get(focusNpcIndex);
		if (focus != null)
		{
			focus.lastActivityTick = tick;
			if (category == HitCategory.HEAL)
			{
				focus.healingReceived += Math.max(0, amount);
			}
			else if (category != HitCategory.DIRECT_MISS && category != HitCategory.PRAYER_DRAIN)
			{
				focus.damageTaken += Math.max(0, amount);
			}
		}
	}

	@Nullable
	public FightRecord onNpcDeath(int npcIndex, int tick, long nowEpochMs)
	{
		ActiveNpcFight fight = activeNpcs.remove(npcIndex);
		if (fight == null)
		{
			return null;
		}
		if (focusNpcIndex == npcIndex)
		{
			focusNpcIndex = -1;
		}
		if (fight.hitsLanded == 0 && fight.misses == 0 && fight.statusDamage == 0)
		{
			if (activeNpcs.isEmpty())
			{
				endActiveBoutDiscardingTail();
			}
			return null;
		}
		// Ignore deaths of NPCs the player abandoned long ago (e.g. finished off later by another player).
		if ((tick - fight.lastActivityTick) > Math.max(idleTimeoutTicks + 5, 20))
		{
			return null;
		}

		// Commit ticks up to the kill tick, then immediately pause Active DPS if no other engaged NPCs remain.
		flushPendingActiveTicks();
		if (activeNpcs.isEmpty())
		{
			recordSparklineSample(tick);
			inActiveBout = false;
			pendingActiveTicks = 0;
			pendingWeaponTicks.clear();
		}

		int effectiveEndTick = Math.min(tick, fight.lastActivityTick + 4);
		int durationTicks = Math.max(1, (effectiveEndTick - fight.firstHitTick) + 1);
		long allocatedSupplyCost = unattributedSupplyCostGp;
		unattributedSupplyCostGp = 0L;

		if (fight.lastDirectDamage > 0)
		{
			totalKillingHitDamage += fight.lastDirectDamage;
			killingHitCount++;
		}

		FightRecord record = FightRecord.builder()
			.npcName(fight.npcName)
			.combatLevel(fight.combatLevel)
			.durationTicks(durationTicks)
			.directDamage(fight.directDamage)
			.statusDamage(fight.statusDamage)
			.hitsLanded(fight.hitsLanded)
			.misses(fight.misses)
			.maxHit(fight.maxHit)
			.damageTaken(fight.damageTaken)
			.healingReceived(fight.healingReceived)
			.supplyCostGp(allocatedSupplyCost)
			.killingHitDamage(fight.lastDirectDamage)
			.primaryWeaponName(fight.getPrimaryWeaponName())
			.completedAtEpochMs(nowEpochMs)
			.build();

		sessionKills++;
		recentFights.addFirst(record);
		while (recentFights.size() > MAX_RECENT_FIGHTS)
		{
			recentFights.removeLast();
		}

		TargetSummary summary = targetSummaries.computeIfAbsent(fight.npcName,
			name -> TargetSummary.builder()
				.npcName(name)
				.combatLevel(fight.combatLevel)
				.build());
		summary.mergeFight(record);
		return record;
	}

	public void loadPersistedSummaries(List<TargetSummary> summaries)
	{
		targetSummaries.clear();
		if (summaries == null)
		{
			return;
		}
		for (TargetSummary summary : summaries)
		{
			if (summary != null && summary.getNpcName() != null && !summary.getNpcName().trim().isEmpty())
			{
				targetSummaries.put(summary.getNpcName(), summary);
			}
		}
	}

	public List<TargetSummary> getTargetSummariesSorted()
	{
		List<TargetSummary> list = new ArrayList<>(targetSummaries.values());
		list.sort(Comparator.comparingLong(TargetSummary::getLastKilledEpochMs).reversed()
			.thenComparingInt(TargetSummary::getKills).reversed());
		return Collections.unmodifiableList(list);
	}

	public void resetSessionOnly()
	{
		sessionStarted = false;
		paused = false;
		inActiveBout = false;
		activeTicks = 0;
		pendingActiveTicks = 0;
		pendingWeaponTicks.clear();
		lastActiveTickCounted = -10000;
		sessionTicks = 0;
		lastCombatTick = -10000;
		totalDirectDamage = 0;
		totalHitsLanded = 0;
		totalMisses = 0;
		sessionKills = 0;
		currentHitStreak = 0;
		bestHitStreak = 0;
		currentMissStreak = 0;
		worstMissStreak = 0;
		totalKillingHitDamage = 0;
		killingHitCount = 0;
		rollingWindow.clear();
		rollingWindowDamage = 0;
		dpsSparkline.clear();
		lastSparklineTick = -10000;
		lastSpecUsedTick = -100;
		specUses = 0;
		specHits = 0;
		specMisses = 0;
		specTotalDamage = 0;
		specMaxHit = 0;
		xpGainedBySkill.clear();
		pendingPreSessionXp.clear();
		pendingPreSessionXpTick = -10000;
		totalCombatXpGained = 0;
		focusNpcIndex = -1;
		lastTargetName = "";
		lastTargetCombatLevel = 0;
		unattributedSupplyCostGp = 0L;
		hitDistribution.reset();
		statusAndDefense.reset();
		weaponStatsById.clear();
		activeNpcs.clear();
		recentFights.clear();
	}

	public void clearPersistedHistory()
	{
		targetSummaries.clear();
		recentFights.clear();
	}

	public SessionSnapshot snapshot()
	{
		StatusDamageBreakdown.Snapshot statusSnap = statusAndDefense.toSnapshot();
		boolean activelyFighting = isInActiveCombat();
		boolean includePending = activelyFighting && !activeNpcs.isEmpty();
		int effectiveActiveTicks = activeTicks + (includePending ? pendingActiveTicks : 0);

		List<WeaponStats.Snapshot> weapons = new ArrayList<>(weaponStatsById.size());
		for (Map.Entry<Integer, WeaponStats> entry : weaponStatsById.entrySet())
		{
			int extra = includePending ? pendingWeaponTicks.getOrDefault(entry.getKey(), 0) : 0;
			weapons.add(entry.getValue().toSnapshot(extra));
		}
		weapons.sort(Comparator.comparingLong(WeaponStats.Snapshot::getTotalDamage).reversed());

		ActiveNpcFight focus = activeNpcs.get(focusNpcIndex);
		String activeTargetName = focus != null ? focus.npcName : lastTargetName;
		int activeTargetLvl = focus != null ? focus.combatLevel : lastTargetCombatLevel;
		int activeFightTicks = focus != null ? Math.max(1, (currentTick - focus.firstHitTick) + 1) : 0;
		long activeFightDamage = focus != null ? (focus.directDamage + focus.statusDamage) : 0L;

		double sessionSec = sessionTicks * WeaponStats.SECONDS_PER_TICK;
		double rollingSec = Math.min(ROLLING_WINDOW_TICKS * WeaponStats.SECONDS_PER_TICK,
			Math.max(WeaponStats.SECONDS_PER_TICK, Math.max(effectiveActiveTicks, 1) * WeaponStats.SECONDS_PER_TICK));
		double rolling30sDps = rollingWindowDamage > 0 ? (rollingWindowDamage / rollingSec) : 0.0;

		List<SkillXpEntry> skillXp = new ArrayList<>(xpGainedBySkill.size());
		double sessionHours = Math.max(WeaponStats.SECONDS_PER_TICK, sessionSec) / 3600.0;
		for (Map.Entry<Skill, Long> e : xpGainedBySkill.entrySet())
		{
			if (e.getValue() > 0)
			{
				skillXp.add(new SkillXpEntry(e.getKey(), e.getValue(), sessionSec > 0 ? e.getValue() / sessionHours : 0.0));
			}
		}
		skillXp.sort(Comparator.comparingLong(SkillXpEntry::getXpGained).reversed());

		SpecSnapshot specSnap = new SpecSnapshot(specUses, specHits, specMisses, specTotalDamage, specMaxHit);
		double avgKillingHit = killingHitCount > 0 ? ((double) totalKillingHitDamage) / killingHitCount : 0.0;

		return new SessionSnapshot(
			sessionStarted,
			paused,
			activelyFighting,
			effectiveActiveTicks,
			sessionTicks,
			activeTargetName,
			activeTargetLvl,
			activeFightTicks,
			activeFightDamage,
			totalDirectDamage,
			statusSnap.getTotalStatusDealt(),
			totalHitsLanded,
			totalMisses,
			hitDistribution.getMaxHit(),
			hitDistribution.getNativeMaxSplats(),
			sessionKills,
			rolling30sDps,
			bestHitStreak,
			worstMissStreak,
			avgKillingHit,
			totalCombatXpGained,
			Collections.unmodifiableList(skillXp),
			specSnap,
			Collections.unmodifiableList(new ArrayList<>(dpsSparkline)),
			pinnedComparison,
			Collections.unmodifiableList(hitDistribution.toBuckets()),
			statusSnap,
			Collections.unmodifiableList(weapons),
			Collections.unmodifiableList(new ArrayList<>(recentFights)),
			getTargetSummariesSorted()
		);
	}

	public String formatSummaryText(long sessionSupplyCostGp, long sessionLootGp, boolean showGp)
	{
		SessionSnapshot s = snapshot();
		StringBuilder sb = new StringBuilder();
		sb.append("Combat Breakdown Summary\n");
		if (!s.getActiveTargetName().isEmpty())
		{
			sb.append("Target: ").append(s.getActiveTargetName());
			if (s.getActiveTargetCombatLevel() > 0)
			{
				sb.append(" (lvl ").append(s.getActiveTargetCombatLevel()).append(")");
			}
			sb.append('\n');
		}
		sb.append(String.format(Locale.US,
			"Active DPS: %.2f (%s) | Session DPS: %.2f (%s) | 30s DPS: %.2f\n",
			s.getActiveDps(), formatDuration(s.getActiveSeconds()),
			s.getSessionDps(), formatDuration(s.getSessionSeconds()),
			s.getRolling30sDps()));
		sb.append(String.format(Locale.US,
			"Damage: %,d (Direct %,d + Status %,d) | Accuracy: %.1f%% (%d/%d) | Max Hit: %d (%d max splats)\n",
			s.getTotalDamage(), s.getTotalDirectDamage(), s.getTotalStatusDamage(),
			s.getAccuracyPercent(), s.getTotalHitsLanded(), s.getTotalSwings(),
			s.getMaxHit(), s.getNativeMaxSplats()));
		sb.append(String.format(Locale.US,
			"Kills: %d | Best Hit Streak: %d | Worst Miss Streak: %d | Taken: %,d | Healed: %,d\n",
			s.getSessionKills(), s.getBestHitStreak(), s.getWorstMissStreak(),
			s.getStatusAndDefense().getTotalDamageTaken(),
			s.getStatusAndDefense().getHealingReceived()));
		if (s.getTotalCombatXpGained() > 0)
		{
			sb.append(String.format(Locale.US, "Combat XP: %,d (%,.0f/hr)\n",
				s.getTotalCombatXpGained(), s.getCombatXpPerHour()));
		}
		if (s.getSpec().getUses() > 0)
		{
			sb.append(String.format(Locale.US, "Specs: %d uses | %.1f%% acc | avg %.1f | max %d\n",
				s.getSpec().getUses(), s.getSpec().getAccuracyPercent(),
				s.getSpec().getAveragePerUse(), s.getSpec().getMaxHit()));
		}
		if (showGp && (sessionSupplyCostGp > 0 || sessionLootGp > 0))
		{
			sb.append(String.format(Locale.US, "Loot: %,d gp | Burn: %,d gp | Net: %,d gp\n",
				sessionLootGp, sessionSupplyCostGp, sessionLootGp - sessionSupplyCostGp));
		}
		if (!s.getWeapons().isEmpty())
		{
			sb.append("Weapons:\n");
			for (WeaponStats.Snapshot w : s.getWeapons())
			{
				sb.append(String.format(Locale.US,
					"  - %s: %.2f DPS | %.1f%% acc | avg %.1f | max %d (%d swings)\n",
					w.getWeaponName(), w.getActiveDps(), w.getAccuracyPercent(),
					w.getAverageLandedHit(), w.getMaxHit(), w.getTotalSwings()));
			}
		}
		return sb.toString().trim();
	}

	public String formatHistoryCsv()
	{
		StringBuilder sb = new StringBuilder();
		sb.append("NPC,CombatLevel,Kills,AvgKillSec,FastestKillSec,AvgDPS,AccuracyPct,MaxHit,TotalDamage,DamageTaken,LootPerKillGp,SupplyCostPerKillGp,NetProfitPerKillGp\n");
		for (TargetSummary t : getTargetSummariesSorted())
		{
			sb.append(escapeCsv(t.getNpcName())).append(',')
