package com.combatbreakdown.model;

import lombok.Value;

public final class SupplyUsage
{
	private final String key;
	private final String displayName;
	private final int iconItemId;
	private final SupplyCategory category;
	private long unitsConsumed;
	private long totalCostGp;

	public SupplyUsage(String key, String displayName, int iconItemId, SupplyCategory category)
	{
		this.key = key;
		this.displayName = displayName;
		this.iconItemId = iconItemId;
		this.category = category;
	}

	public void add(long units, long gpCost)
	{
		if (units > 0)
		{
			unitsConsumed += units;
		}
		if (gpCost > 0)
		{
			totalCostGp += gpCost;
		}
	}

	public Snapshot toSnapshot()
	{
		return new Snapshot(key, displayName, iconItemId, category, unitsConsumed, totalCostGp);
	}

	@Value
	public static class Snapshot
	{
		String key;
		String displayName;
		int iconItemId;
		SupplyCategory category;
		long unitsConsumed;
		long totalCostGp;

		public double getUnitsPerHour(double sessionSeconds)
		{
			if (unitsConsumed <= 0 || sessionSeconds <= 0)
			{
				return 0.0;
			}
			double hours = Math.max(WeaponStats.SECONDS_PER_TICK, sessionSeconds) / 3600.0;
			return unitsConsumed / hours;
		}

		public double getUnitsPerKill(int kills)
		{
			return kills > 0 ? ((double) unitsConsumed) / kills : 0.0;
		}

		public long getGpPerHour(double sessionSeconds)
		{
			if (totalCostGp <= 0 || sessionSeconds <= 0)
			{
				return 0L;
			}
			double hours = Math.max(WeaponStats.SECONDS_PER_TICK, sessionSeconds) / 3600.0;
			return Math.round(totalCostGp / hours);
		}
	}
}

package com.combatbreakdown.model;

import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class TargetSummary
{
	private String npcName;
	private int combatLevel;
	private int kills;
	private long totalDurationTicks;
	private int fastestKillTicks;
	private int slowestKillTicks;
	private long totalDirectDamage;
	private long totalStatusDamage;
	private int totalHitsLanded;
	private int totalMisses;
	private int maxHit;
	private long totalDamageTaken;
	private long totalHealing;
	private long totalSupplyCostGp;
	private long totalLootValueGp;
	private long lastKilledEpochMs;

	public void mergeFight(FightRecord fight)
	{
		if (fight == null)
		{
			return;
		}
		if (combatLevel <= 0 && fight.getCombatLevel() > 0)
		{
			combatLevel = fight.getCombatLevel();
		}
		kills++;
		int dur = Math.max(1, fight.getDurationTicks());
		totalDurationTicks += dur;
		if (fastestKillTicks <= 0 || dur < fastestKillTicks)
		{
			fastestKillTicks = dur;
		}
		if (dur > slowestKillTicks)
		{
			slowestKillTicks = dur;
		}
		totalDirectDamage += fight.getDirectDamage();
		totalStatusDamage += fight.getStatusDamage();
		totalHitsLanded += fight.getHitsLanded();
		totalMisses += fight.getMisses();
		if (fight.getMaxHit() > maxHit)
		{
			maxHit = fight.getMaxHit();
		}
		totalDamageTaken += fight.getDamageTaken();
		totalHealing += fight.getHealingReceived();
		totalSupplyCostGp += fight.getSupplyCostGp();
		totalLootValueGp += fight.getLootValueGp();
		lastKilledEpochMs = Math.max(lastKilledEpochMs, fight.getCompletedAtEpochMs());
	}

	public void addLootValueGp(long lootGp)
	{
		if (lootGp > 0)
		{
			totalLootValueGp += lootGp;
		}
	}

	public long getTotalDamage()
	{
		return totalDirectDamage + totalStatusDamage;
	}

	public double getAverageKillSeconds()
	{
		return kills > 0 ? (totalDurationTicks * WeaponStats.SECONDS_PER_TICK) / kills : 0.0;
	}

	public double getFastestKillSeconds()
	{
		return fastestKillTicks * WeaponStats.SECONDS_PER_TICK;
	}

	public double getAverageDps()
	{
		double seconds = Math.max(WeaponStats.SECONDS_PER_TICK, totalDurationTicks * WeaponStats.SECONDS_PER_TICK);
		return getTotalDamage() > 0 ? getTotalDamage() / seconds : 0.0;
	}

	public double getAccuracyPercent()
	{
		int total = totalHitsLanded + totalMisses;
		return total > 0 ? (totalHitsLanded * 100.0) / total : 0.0;
	}

	public long getSupplyCostPerKillGp()
	{
		return kills > 0 ? totalSupplyCostGp / kills : 0L;
	}

	public long getLootPerKillGp()
	{
		return kills > 0 ? totalLootValueGp / kills : 0L;
	}

	public long getNetProfitPerKillGp()
	{
		return kills > 0 ? (totalLootValueGp - totalSupplyCostGp) / kills : 0L;
	}
}

package com.combatbreakdown.model;

import lombok.Value;

public final class WeaponStats
{
	public static final double SECONDS_PER_TICK = 0.6;

	private final int weaponItemId;
	private final String weaponName;
	private int hitsLanded;
	private int misses;
	private long totalDamage;
	private int maxHit;
	private int nativeMaxSplats;
	private int activeTicks;

	public WeaponStats(int weaponItemId, String weaponName)
	{
		this.weaponItemId = weaponItemId;
		this.weaponName = weaponName != null && !weaponName.isEmpty() ? weaponName : "Unarmed";
	}

	public void recordHit(int damage, boolean nativeMaxSplat)
	{
		if (damage <= 0)
		{
			misses++;
			return;
		}
		hitsLanded++;
		totalDamage += damage;
		if (damage > maxHit)
		{
			maxHit = damage;
		}
		if (nativeMaxSplat)
		{
			nativeMaxSplats++;
		}
	}

	public void addActiveTick()
	{
		activeTicks++;
	}

	public Snapshot toSnapshot()
	{
		return toSnapshot(0);
	}

	public Snapshot toSnapshot(int pendingActiveTicks)
	{
		return new Snapshot(
			weaponItemId,
			weaponName,
			hitsLanded,
			misses,
			totalDamage,
			maxHit,
			nativeMaxSplats,
			activeTicks + Math.max(0, pendingActiveTicks)
		);
	}

	@Value
	public static class Snapshot
	{
		int weaponItemId;
		String weaponName;
		int hitsLanded;
		int misses;
		long totalDamage;
		int maxHit;
		int nativeMaxSplats;
		int activeTicks;

		public int getTotalSwings()
		{
			return hitsLanded + misses;
		}

		public double getAccuracyPercent()
		{
			int total = getTotalSwings();
			return total > 0 ? (hitsLanded * 100.0) / total : 0.0;
		}

		public double getAverageLandedHit()
		{
			return hitsLanded > 0 ? ((double) totalDamage) / hitsLanded : 0.0;
		}

		public double getAveragePerSwing()
		{
			int total = getTotalSwings();
			return total > 0 ? ((double) totalDamage) / total : 0.0;
		}

		public double getActiveDps()
		{
			double seconds = Math.max(SECONDS_PER_TICK, activeTicks * SECONDS_PER_TICK);
			return totalDamage > 0 ? totalDamage / seconds : 0.0;
		}
	}
}

